# Hindi / Gujarati text for Economics Ch 5 lesson, sections 4-5.
TEXT_B = {
 "s4.thm.title": ("उपभोक्ता आयोग और मानकीकरण", "ગ્રાહક પંચો અને ધોરણીકરણ"),
 "s4.thm.body": (
  "**उपभोक्ता आयोग:** उपभोक्ता संरक्षण अधिनियम के तहत उपभोक्ता विवाद सुलझाने के लिए **ज़िला, राज्य और राष्ट्रीय स्तर** पर **त्रिस्तरीय अर्ध-न्यायिक तंत्र** बनाया गया है। इन्हें आमतौर पर **उपभोक्ता अदालतें** कहा जाता है।\n"
  "- **ज़िला उपभोक्ता विवाद निवारण आयोग** **Rs 50 लाख** तक के दावों के मामले देखता है (2019 के अधिनियम के तहत 2021 के नियमों के अनुसार)।\n"
  "- **राज्य आयोग** Rs 50 लाख से ऊपर और **Rs 2 करोड़** तक के दावे देखता है।\n"
  "- नई दिल्ली स्थित **राष्ट्रीय आयोग** **Rs 2 करोड़** से ऊपर के दावे देखता है।\n"
  "- अगर ज़िला स्तर पर मामला ख़ारिज हो जाए, तो उपभोक्ता राज्य आयोग में और फिर राष्ट्रीय आयोग में **अपील** कर सकता है।\n"
  "- उपभोक्ता ख़ुद शिकायत दर्ज कर सकते हैं; उन्हें हमेशा वकील की ज़रूरत नहीं। उपभोक्ता समूह भी उपभोक्ताओं को मामला दर्ज करने का **मार्गदर्शन** देते हैं और अक्सर उनका **प्रतिनिधित्व** करते हैं।\n\n"
  "**उत्पादों का मानकीकरण:** मानक चिह्न ख़रीदारी के समय उपभोक्ताओं को गुणवत्ता का भरोसा देते हैं।\n"
  "- **ISI चिह्न:** औद्योगिक और उपभोक्ता वस्तुओं के लिए **भारतीय मानक ब्यूरो (BIS)** द्वारा दिया जाता है।\n"
  "- **एगमार्क:** खाद्य तेल, अनाज और शहद जैसे **कृषि उत्पादों** के लिए।\n"
  "- **हॉलमार्क:** **सोने और चाँदी के गहनों** के लिए, BIS द्वारा प्रमाणित।\n"
  "- **ISO:** गुणवत्ता के अंतरराष्ट्रीय मानक।\n"
  "- उपभोक्ताओं के **स्वास्थ्य और सुरक्षा** को प्रभावित करने वाले कुछ उत्पादों, जैसे **LPG सिलेंडर, खाद्य रंग और योजक, सीमेंट और बोतलबंद पेयजल**, के लिए उत्पादकों को इन संगठनों से प्रमाणन लेना **अनिवार्य** है।\n\n"
  "**उपभोक्ता आंदोलन की प्रगति:** भारत में **24 दिसंबर** को **राष्ट्रीय उपभोक्ता दिवस** मनाया जाता है, क्योंकि इसी दिन 1986 में कोपरा पारित हुआ था। भारत में सैकड़ों उपभोक्ता समूह हैं, पर उनमें से कुछ ही अच्छी तरह संगठित हैं। निवारण की प्रक्रिया अक्सर **जटिल, महँगी और समय लेने वाली** होती है; कई उपभोक्ता बिल नहीं रखते, और क़ानूनों का पालन हमेशा नहीं होता। इसलिए उपभोक्ताओं को **जागरूक और सक्रिय** होना चाहिए, और आंदोलन में सबकी स्वैच्छिक भागीदारी चाहिए।",
  "**ગ્રાહક પંચો:** ગ્રાહક સુરક્ષા ધારા હેઠળ ગ્રાહક વિવાદો ઉકેલવા **જિલ્લા, રાજ્ય અને રાષ્ટ્રીય સ્તરે** **ત્રિસ્તરીય અર્ધ-ન્યાયિક તંત્ર** રચાયું છે. તેને સામાન્ય રીતે **ગ્રાહક અદાલતો** કહે છે.\n"
  "- **જિલ્લા ગ્રાહક તકરાર નિવારણ પંચ** **Rs 50 લાખ** સુધીના દાવાના કેસો સાંભળે છે (2019ના ધારા હેઠળના 2021ના નિયમો મુજબ).\n"
  "- **રાજ્ય પંચ** Rs 50 લાખથી વધુ અને **Rs 2 કરોડ** સુધીના દાવા સાંભળે છે.\n"
  "- નવી દિલ્હીનું **રાષ્ટ્રીય પંચ** **Rs 2 કરોડ**થી વધુના દાવા સાંભળે છે.\n"
  "- જો જિલ્લા સ્તરે કેસ રદ થાય, તો ગ્રાહક રાજ્ય પંચમાં અને પછી રાષ્ટ્રીય પંચમાં **અપીલ** કરી શકે.\n"
  "- ગ્રાહકો પોતે ફરિયાદ નોંધાવી શકે; તેમને હંમેશાં વકીલની જરૂર નથી. ગ્રાહક જૂથો પણ ગ્રાહકોને કેસ નોંધાવવાનું **માર્ગદર્શન** આપે છે અને ઘણી વાર તેમનું **પ્રતિનિધિત્વ** કરે છે.\n\n"
  "**ઉત્પાદનોનું ધોરણીકરણ:** ધોરણ ચિહ્નો ખરીદી વખતે ગ્રાહકોને ગુણવત્તાની ખાતરી આપે છે.\n"
  "- **ISI ચિહ્ન:** ઔદ્યોગિક અને ગ્રાહક વસ્તુઓ માટે **ભારતીય માનક બ્યુરો (BIS)** દ્વારા અપાય છે.\n"
  "- **ઍગમાર્ક:** ખાદ્યતેલ, અનાજ અને મધ જેવી **કૃષિ પેદાશો** માટે.\n"
  "- **હૉલમાર્ક:** **સોના અને ચાંદીના દાગીના** માટે, BIS દ્વારા પ્રમાણિત.\n"
  "- **ISO:** ગુણવત્તાનાં આંતરરાષ્ટ્રીય ધોરણો.\n"
  "- ગ્રાહકોના **આરોગ્ય અને સલામતી**ને અસર કરતાં કેટલાંક ઉત્પાદનો, જેમ કે **LPG સિલિન્ડર, ખાદ્ય રંગો અને ઉમેરણો, સિમેન્ટ અને બાટલીબંધ પીવાનું પાણી**, માટે ઉત્પાદકોએ આ સંસ્થાઓનું પ્રમાણપત્ર લેવું **ફરજિયાત** છે.\n\n"
  "**ગ્રાહક આંદોલનની પ્રગતિ:** ભારતમાં **24 ડિસેમ્બર**ને **રાષ્ટ્રીય ગ્રાહક દિવસ** તરીકે ઊજવાય છે, કારણ કે આ દિવસે 1986માં COPRA પસાર થયો હતો. ભારતમાં સેંકડો ગ્રાહક જૂથો છે, પણ તેમાંથી થોડાં જ સારી રીતે સંગઠિત છે. નિવારણની પ્રક્રિયા ઘણી વાર **જટિલ, ખર્ચાળ અને સમય લેનારી** હોય છે; ઘણા ગ્રાહકો બિલ રાખતા નથી, અને કાયદાનો અમલ હંમેશાં થતો નથી. તેથી ગ્રાહકોએ **જાગૃત અને સક્રિય** બનવું જોઈએ, અને આંદોલનમાં બધાની સ્વૈચ્છિક ભાગીદારી જોઈએ."),
 "s4.table.title": ("त्रिस्तरीय उपभोक्ता आयोग", "ત્રિસ્તરીય ગ્રાહક પંચો"),
 "s4.table.body": (
  "| स्तर | नाम | सुने जाने वाले दावों की राशि (2021 के नियम) |\n|---|---|---|\n| **ज़िला स्तर** | ज़िला उपभोक्ता विवाद निवारण आयोग | Rs 50 लाख तक |\n"
  "| **राज्य स्तर** | राज्य आयोग | Rs 50 लाख से ऊपर Rs 2 करोड़ तक |\n| **राष्ट्रीय स्तर** | राष्ट्रीय आयोग (नई दिल्ली) | Rs 2 करोड़ से ऊपर |",
  "| સ્તર | નામ | સાંભળવામાં આવતા દાવાની રકમ (2021ના નિયમો) |\n|---|---|---|\n| **જિલ્લા સ્તર** | જિલ્લા ગ્રાહક તકરાર નિવારણ પંચ | Rs 50 લાખ સુધી |\n"
  "| **રાજ્ય સ્તર** | રાજ્ય પંચ | Rs 50 લાખથી વધુ Rs 2 કરોડ સુધી |\n| **રાષ્ટ્રીય સ્તર** | રાષ્ટ્રીય પંચ (નવી દિલ્હી) | Rs 2 કરોડથી વધુ |"),
 "s5.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s5.memory.body": (
  "- **छह अधिकार \"सु-सू-चु-नि-प्र-शि\"**: सुरक्षा, सूचना, चुनना, निवारण, प्रतिनिधित्व, शिक्षा।\n- **शोषण के कारण \"जानकारी, आपूर्ति, प्रतिस्पर्धा, साक्षरता\"** (सब सीमित/कम)।\n"
  "- **तिथियाँ: कोपरा 1986 (24 दिसंबर = राष्ट्रीय उपभोक्ता दिवस); CPA 2019; RTI 2005; 15 मार्च = विश्व उपभोक्ता अधिकार दिवस।**\n"
  "- **चिह्न: ISI = उद्योग, एगमार्क = कृषि, हॉलमार्क = गहने।**\n- **तीन स्तर: ज़िला → राज्य → राष्ट्रीय।**",
  "- **છ અધિકારો \"સ-મા-પ-નિ-પ્ર-શિ\"**: સલામતી, માહિતી, પસંદગી, નિવારણ, પ્રતિનિધિત્વ, શિક્ષણ.\n- **શોષણનાં કારણો \"માહિતી, પુરવઠો, સ્પર્ધા, સાક્ષરતા\"** (બધાં મર્યાદિત/ઓછાં).\n"
  "- **તારીખો: COPRA 1986 (24 ડિસેમ્બર = રાષ્ટ્રીય ગ્રાહક દિવસ); CPA 2019; RTI 2005; 15 માર્ચ = વિશ્વ ગ્રાહક અધિકાર દિવસ.**\n"
  "- **ચિહ્નો: ISI = ઉદ્યોગ, ઍગમાર્ક = ખેતી, હૉલમાર્ક = દાગીના.**\n- **ત્રણ સ્તર: જિલ્લો → રાજ્ય → રાષ્ટ્રીય.**"),
 "s5.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s5.mistakes.body": (
  "1. शहद के लिए हॉलमार्क बताना: शहद और खाद्य तेल पर **एगमार्क** होता है; हॉलमार्क **गहनों** के लिए है।\n2. उपभोक्ता अदालतों को सामान्य फ़ौजदारी अदालतें कहना: ये **अर्ध-न्यायिक उपभोक्ता आयोग** हैं।\n"
  "3. राष्ट्रीय उपभोक्ता दिवस (**24 दिसंबर**, भारत) को विश्व उपभोक्ता अधिकार दिवस (**15 मार्च**) से मिलाना।\n4. यह सोचना कि उपभोक्ता को MRP से ज़्यादा देना पड़ता है: **MRP से ज़्यादा** लेना अनुचित है और इसकी शिकायत हो सकती है।\n"
  "5. भूल जाना कि 2025-26 में यह अध्याय **परियोजना** के लिए है, बोर्ड परीक्षा के लिए नहीं।",
  "1. મધ માટે હૉલમાર્ક જણાવવું: મધ અને ખાદ્યતેલ પર **ઍગમાર્ક** હોય છે; હૉલમાર્ક **દાગીના** માટે છે.\n2. ગ્રાહક અદાલતોને સામાન્ય ફોજદારી અદાલતો કહેવી: તે **અર્ધ-ન્યાયિક ગ્રાહક પંચો** છે.\n"
  "3. રાષ્ટ્રીય ગ્રાહક દિવસ (**24 ડિસેમ્બર**, ભારત)ને વિશ્વ ગ્રાહક અધિકાર દિવસ (**15 માર્ચ**) સાથે ભેળવવો.\n4. માનવું કે ગ્રાહકે MRP કરતાં વધુ ચૂકવવું પડે: **MRP કરતાં વધુ** લેવું અયોગ્ય છે અને તેની ફરિયાદ થઈ શકે.\n"
  "5. ભૂલી જવું કે 2025-26માં આ પ્રકરણ **પ્રોજેક્ટ** માટે છે, બોર્ડ પરીક્ષા માટે નહિ."),
 "s5.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s5.tip.body": (
  "छात्रों से पाँच ख़ाली पैकेट (खाना, दवा, सौंदर्य प्रसाधन) लाने को कहिए। समूहों में हर पैकेट पर MRP, निर्माण तिथि, अंतिम तिथि, मानक चिह्न और ग्राहक सेवा नंबर की सूची बनाइए। चर्चा कीजिए कि हर जानकारी किस अधिकार में मदद करती है। इससे उपभोक्ता अधिकार परियोजना शुरू हो सकती है।",
  "વિદ્યાર્થીઓને પાંચ ખાલી પૅકેટ (ખોરાક, દવા, સૌંદર્ય પ્રસાધન) લાવવા કહો. જૂથોમાં દરેક પૅકેટ પર MRP, ઉત્પાદન તારીખ, અંતિમ તારીખ, ધોરણ ચિહ્ન અને ગ્રાહક સેવા નંબરની યાદી બનાવો. ચર્ચા કરો કે દરેક માહિતી કયા અધિકારમાં મદદ કરે છે. તેનાથી ગ્રાહક અધિકાર પ્રોજેક્ટ શરૂ થઈ શકે."),
 "s5.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s5.reflection.body": (
  "क्या आपसे या आपके परिवार से कभी ज़्यादा पैसे लिए गए या कोई दोषपूर्ण उत्पाद बेचा गया? आपने क्या किया? आप कौन-सा उपभोक्ता अधिकार इस्तेमाल कर सकते थे?",
  "શું તમારી કે તમારા પરિવાર પાસેથી ક્યારેય વધુ પૈસા લેવાયા કે કોઈ ખામીવાળું ઉત્પાદન વેચાયું? તમે શું કર્યું? તમે કયો ગ્રાહક અધિકાર વાપરી શક્યા હોત?"),
 "s5.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s5.connection.body": (
  "- **अध्याय 3 (मुद्रा और साख):** उपभोक्ताओं के लिए उचित ऋण शर्तें।\n- **अध्याय 4 (वैश्वीकरण):** बाज़ार में कई ब्रांड और विकल्प।\n"
  "- **राजनीति विज्ञान अध्याय 5 (लोकतंत्र के परिणाम):** सूचना का अधिकार और जवाबदेही।",
  "- **પ્રકરણ 3 (નાણું અને શાખ):** ગ્રાહકો માટે યોગ્ય ધિરાણ શરતો.\n- **પ્રકરણ 4 (વૈશ્વિકીકરણ):** બજારમાં અનેક બ્રાન્ડ અને વિકલ્પો.\n"
  "- **રાજ્યશાસ્ત્ર પ્રકરણ 5 (લોકશાહીનાં પરિણામો):** માહિતીનો અધિકાર અને જવાબદારી."),
 "s5.mastery.title": ("महारत चुनौती (परियोजना की शुरुआत)", "નિપુણતા પડકાર (પ્રોજેક્ટની શરૂઆત)"),
 "s5.mastery.body": (
  "'जागरूक उपभोक्ता ही सुरक्षित उपभोक्ता है।' लगभग 120 शब्दों में समझाइए।\n\n"
  "**आदर्श उत्तर:** उपभोक्ताओं का शोषण कम तौल, मिलावट, दोषपूर्ण वस्तुओं, MRP से ज़्यादा क़ीमत और भ्रामक विज्ञापनों से होता है, मुख्यतः सीमित जानकारी, सीमित आपूर्ति, सीमित प्रतिस्पर्धा और कम साक्षरता के कारण। "
  "जागरूक उपभोक्ता MRP, अवयव, निर्माण तिथि और अंतिम तिथि जाँचता है, ISI, एगमार्क और हॉलमार्क जैसे मानक चिह्न देखता है, और बिल लेता है। "
  "ऐसा उपभोक्ता सुरक्षा, सूचना, चुनने, निवारण, प्रतिनिधित्व और शिक्षा के अधिकार जानता है, और उपभोक्ता संरक्षण अधिनियम, 2019 के तहत ज़िला, राज्य या राष्ट्रीय उपभोक्ता आयोग में जा सकता है। उपभोक्ता समूह मार्गदर्शन और प्रतिनिधित्व से मदद करते हैं। इस तरह जागरूकता काग़ज़ के अधिकारों को असली सुरक्षा में बदल देती है।",
  "'જાગૃત ગ્રાહક જ સુરક્ષિત ગ્રાહક છે.' આશરે 120 શબ્દોમાં સમજાવો.\n\n"
  "**આદર્શ જવાબ:** ગ્રાહકોનું શોષણ ઓછું તોલવું, ભેળસેળ, ખામીવાળી વસ્તુઓ, MRP કરતાં વધુ કિંમત અને ભ્રામક જાહેરખબરોથી થાય છે, મુખ્યત્વે મર્યાદિત માહિતી, મર્યાદિત પુરવઠો, મર્યાદિત સ્પર્ધા અને ઓછી સાક્ષરતાને કારણે. "
  "જાગૃત ગ્રાહક MRP, ઘટકો, ઉત્પાદન તારીખ અને અંતિમ તારીખ તપાસે છે, ISI, ઍગમાર્ક અને હૉલમાર્ક જેવાં ધોરણ ચિહ્નો જુએ છે, અને બિલ લે છે. "
  "આવો ગ્રાહક સલામતી, માહિતી, પસંદગી, નિવારણ, પ્રતિનિધિત્વ અને શિક્ષણના અધિકારો જાણે છે, અને ગ્રાહક સુરક્ષા ધારો, 2019 હેઠળ જિલ્લા, રાજ્ય કે રાષ્ટ્રીય ગ્રાહક પંચમાં જઈ શકે છે. ગ્રાહક જૂથો માર્ગદર્શન અને પ્રતિનિધિત્વથી મદદ કરે છે. આમ જાગૃતિ કાગળ પરના અધિકારોને ખરા રક્ષણમાં ફેરવે છે."),
 "s5.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s5.summary.body": (
  "- उपभोक्ता अक्सर कमज़ोर स्थिति में होते हैं और कम तौल, मिलावट, दोषपूर्ण वस्तुओं, MRP से ज़्यादा क़ीमत और ग़लत जानकारी से उनका शोषण हो सकता है।\n"
  "- शोषण सीमित जानकारी, सीमित आपूर्ति, सीमित प्रतिस्पर्धा और कम साक्षरता से होता है; उपभोक्ताओं की रक्षा के लिए नियम ज़रूरी हैं।\n"
  "- उपभोक्ता आंदोलन 1960 के दशक से बढ़ा; 1986 में कोपरा बना, जिसकी जगह उपभोक्ता संरक्षण अधिनियम, 2019 ने ली।\n"
  "- उपभोक्ताओं को सुरक्षा, सूचना, चुनने, निवारण, प्रतिनिधित्व और शिक्षा के अधिकार हैं; RTI अधिनियम 2005 सरकारी कामकाज की जानकारी देता है।\n"
  "- त्रिस्तरीय उपभोक्ता आयोग (ज़िला, राज्य, राष्ट्रीय) विवाद सुलझाते हैं; ISI, एगमार्क और हॉलमार्क गुणवत्ता का भरोसा देते हैं।\n"
  "- 2025-26 में यह अध्याय परियोजना कार्य के लिए है, बोर्ड परीक्षा के लिए नहीं।",
  "- ગ્રાહકો ઘણી વાર નબળી સ્થિતિમાં હોય છે અને ઓછું તોલવું, ભેળસેળ, ખામીવાળી વસ્તુઓ, MRP કરતાં વધુ કિંમત અને ખોટી માહિતીથી તેમનું શોષણ થઈ શકે.\n"
  "- શોષણ મર્યાદિત માહિતી, મર્યાદિત પુરવઠો, મર્યાદિત સ્પર્ધા અને ઓછી સાક્ષરતાથી થાય છે; ગ્રાહકોના રક્ષણ માટે નિયમો જરૂરી છે.\n"
  "- ગ્રાહક આંદોલન 1960ના દાયકાથી વિકસ્યું; 1986માં COPRA બન્યો, જેનું સ્થાન ગ્રાહક સુરક્ષા ધારો, 2019એ લીધું.\n"
  "- ગ્રાહકોને સલામતી, માહિતી, પસંદગી, નિવારણ, પ્રતિનિધિત્વ અને શિક્ષણના અધિકારો છે; RTI અધિનિયમ 2005 સરકારી કામકાજની માહિતી આપે છે.\n"
  "- ત્રિસ્તરીય ગ્રાહક પંચો (જિલ્લો, રાજ્ય, રાષ્ટ્રીય) વિવાદો ઉકેલે છે; ISI, ઍગમાર્ક અને હૉલમાર્ક ગુણવત્તાની ખાતરી આપે છે.\n"
  "- 2025-26માં આ પ્રકરણ પ્રોજેક્ટ કાર્ય માટે છે, બોર્ડ પરીક્ષા માટે નહિ."),
 "s5.examtips.title": ("परियोजना के सुझाव", "પ્રોજેક્ટ માટેની ટિપ્સ"),
 "s5.examtips.body": (
  "- 2025-26 में उपभोक्ता अधिकार **परियोजना** के विकल्पों में से एक है (आंतरिक मूल्यांकन); यह बोर्ड परीक्षा में **नहीं** है।\n"
  "- अच्छी परियोजना में पैकेटों और बिलों का सर्वेक्षण, किसी असली उपभोक्ता शिकायत का केस स्टडी, उदाहरणों सहित छह उपभोक्ता अधिकार, और त्रिस्तरीय निवारण व्यवस्था हो।\n"
  "- जो बिल और लेबल की फ़ोटो आप इकट्ठा करें, उन्हें परियोजना फ़ाइल में प्रमाण के रूप में रखें।",
  "- 2025-26માં ગ્રાહક અધિકારો **પ્રોજેક્ટ**ના વિકલ્પોમાંનો એક છે (આંતરિક મૂલ્યાંકન); તે બોર્ડ પરીક્ષામાં **નથી**.\n"
  "- સારા પ્રોજેક્ટમાં પૅકેટ અને બિલનું સર્વેક્ષણ, કોઈ ખરી ગ્રાહક ફરિયાદનો કેસ સ્ટડી, ઉદાહરણો સાથે છ ગ્રાહક અધિકારો, અને ત્રિસ્તરીય નિવારણ વ્યવસ્થા હોય.\n"
  "- તમે ભેગાં કરેલાં બિલ અને લેબલના ફોટા પ્રોજેક્ટ ફાઇલમાં પુરાવા તરીકે રાખો."),
 "s5.flash1.front": ("छह उपभोक्ता अधिकार बताइए।", "છ ગ્રાહક અધિકારો જણાવો."),
 "s5.flash1.back": ("सुरक्षा, सूचना, चुनने, क्षतिपूर्ति निवारण, प्रतिनिधित्व और उपभोक्ता शिक्षा का अधिकार।", "સલામતી, માહિતી, પસંદગી, ફરિયાદ નિવારણ, પ્રતિનિધિત્વ અને ગ્રાહક શિક્ષણનો અધિકાર."),
 "s5.flash2.front": ("भारत में राष्ट्रीय उपभोक्ता दिवस कब है?", "ભારતમાં રાષ્ટ્રીય ગ્રાહક દિવસ ક્યારે છે?"),
 "s5.flash2.back": ("24 दिसंबर, जिस दिन 1986 में उपभोक्ता संरक्षण अधिनियम पारित हुआ था।", "24 ડિસેમ્બર, જે દિવસે 1986માં ગ્રાહક સુરક્ષા ધારો પસાર થયો હતો."),
 "s5.flash3.front": ("ISI, एगमार्क और हॉलमार्क क्या प्रमाणित करते हैं?", "ISI, ઍગમાર્ક અને હૉલમાર્ક શું પ્રમાણિત કરે છે?"),
 "s5.flash3.back": ("ISI: औद्योगिक और उपभोक्ता वस्तुएँ (BIS)। एगमार्क: कृषि उत्पाद। हॉलमार्क: सोने और चाँदी के गहने।", "ISI: ઔદ્યોગિક અને ગ્રાહક વસ્તુઓ (BIS). ઍગમાર્ક: કૃષિ પેદાશો. હૉલમાર્ક: સોના અને ચાંદીના દાગીના."),
 "s5.flash4.front": ("उपभोक्ता आयोगों के तीन स्तर कौन-से हैं?", "ગ્રાહક પંચોના ત્રણ સ્તર કયા છે?"),
 "s5.flash4.back": ("ज़िला आयोग, राज्य आयोग और राष्ट्रीय आयोग।", "જિલ્લા પંચ, રાજ્ય પંચ અને રાષ્ટ્રીય પંચ."),
}
